import json,csv,io,hashlib,re,datetime
p=Path('docs/audit/source-readings.json')
a=json.loads(p.read_text()); readings=a['readings'];inv=[];summaries=[]
for s in readings:
 entry={k:v for k,v in s.items() if k not in ('content','paragraphs')}
 entry['extracted_text_sha256']=hashlib.sha256(s['content'].encode()).hexdigest()
 entry['extracted_text_bytes']=len(s['content'].encode())
 if s.get('path','').endswith('.csv'):
  reader=csv.DictReader(io.StringIO(s['content'])); rows=list(reader)
  entry['header']=reader.fieldnames;entry['rows']=len(rows)
  entry['malformed_rows']=sum(None in r or any(v is None for v in r.values()) for r in rows)
 inv.append(entry)
for b in (1,2,3):
 ss=[s for s in readings if s.get('batch')==b]
 readme=next(s['content'] for s in ss if s['path'].endswith('/README.md'))
 expect={name:int(n) for name,n in re.findall(r'\| `([^`]+\.csv)` \| (\d+) \|',readme)}
 actual={s['title']:s['rows'] for s in inv if s.get('batch')==b and 'rows' in s}
 docs=[s for s in ss if re.search(r'/(letters|dispositions|decisions)/',s['path'])]
 correspondence=next(s for s in ss if s['path'].endswith('/correspondence.csv'))
 refs=list(csv.DictReader(io.StringIO(correspondence['content'])))
 paths={s['path'].split('/',1)[1] for s in docs}
 missing=[r['document_path'] for r in refs if r['document_path'] not in paths]
 extra=sorted(paths-set(r['document_path'] for r in refs))
 summaries.append({'batch':b,'csvs':len(actual),'rows':actual,'readme_counts_match':expect==actual,'documents_by_folder':dict(Counter(s['path'].split('/')[1] for s in docs)),'correspondence_rows':len(refs),'missing_referenced_documents':missing,'unindexed_documents':extra})
identity=[]
for s in readings:
 if s.get('path','').endswith('/applications.csv'):
  for r in csv.DictReader(io.StringIO(s['content'])):
   if r['application_id'] in ('APP-2026-017','APP-2026-034','APP-2026-029','APP-2026-025'):
    identity.append({k:r[k] for k in ('application_id','revision','first_name','last_name','cv_received_date','release_signed_date')})
print(json.dumps({'batch_checks':summaries,'malformed_rows':sum(s.get('malformed_rows',0) for s in inv),'selected_identity_evidence':identity,'independent_source_arithmetic':{'gap_2019_04_01_to_2019_11_05_inclusive_days':(datetime.date(2019,11,5)-datetime.date(2019,4,1)).days+1,'letter_2026_02_18_plus_30_days':str(datetime.date(2026,2,18)+datetime.timedelta(days=30))}},indent=2))
Path('docs/audit/source-inventory.json').write_text(json.dumps({'scope':'pre-implementation source/access/structural audit; not computed application states','retrieved_at_utc':a['retrieved_at_utc'],'integrity_note':a['integrity_note'],'sources':inv,'batch_checks':summaries},indent=2)+'\n')
print('Inventory written. Full source record text scan:')
for s in readings:
 if s.get('batch') and re.search(r'signature|signed application|cv|curriculum',s['content'],re.I) and not s.get('path','').endswith('README.md'):
  lines=[l for l in s['content'].splitlines() if re.search(r'application.*sign|sign.*application|curriculum|\bcv\b',l,re.I)]
  if lines:print(s['path'], '\n'.join(lines)[:700])
