                     "signature_date", "first_request_date", "release_signed_date", "cv_received_date", "date"}


def checked_date(value: str, as_of: date, location: str) -> None:
    if not value:
        return  # Missing evidence stays missing; this layer assigns no meaning.
    try:
        if not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value):
            raise ValueError("date shape")
        observed = date.fromisoformat(value)
    except ValueError as exc:
        raise GroundworkError("invalid_date", f"Invalid observation date at {location}") from exc
    if observed > as_of:
        raise GroundworkError("future_evidence", f"Observation after export date at {location}")


def validate_content(manifest: dict, contents: dict[str, bytes]) -> dict:
    """Validate bytes captured from the allowlist without reading other files."""
    manifest_validate(manifest)
    if set(contents) != {entry["path"] for entry in manifest["files"]}:
        raise GroundworkError("source_set", "Only the manifest's exact allowlist may enter state")
    as_of = date.fromisoformat(manifest["as_of"])
    counts = {}
    document_paths = {f["path"] for f in manifest["files"] if f["kind"] == "document"}
    indexed_documents = []
    for entry in manifest["files"]:
        name = entry["path"]
        raw = contents[name]
        if digest(raw) != entry["sha256"]:
            raise GroundworkError("hash_mismatch", f"Source bytes differ from manifest: {name}")
        try:
            text = raw.decode("utf-8")
        except UnicodeError as exc:
            raise GroundworkError("invalid_encoding", f"Source is not UTF-8: {name}") from exc
        if entry["kind"] == "records":
            try:
                reader = csv.DictReader(io.StringIO(text, newline=""), strict=True)
                if reader.fieldnames != LAYOUT[name].split(","):
                    raise GroundworkError("csv_header", f"Unexpected CSV columns: {name}")
                rows = list(reader)
                for number, row in enumerate(rows, 2):
                    if None in row or any(value is None for value in row.values()):
                        raise GroundworkError("csv_width", f"Malformed CSV row: {name}:{number}")
                    for column in OBSERVATION_DATES & row.keys():
                        checked_date(row[column], as_of, f"{name}:{number}:{column}")
                    if name == "correspondence.csv":
                        indexed_documents.append(relative_path(row["document_path"]))
                counts[name] = len(rows)
            except csv.Error as exc:
                raise GroundworkError("invalid_csv", f"Invalid CSV syntax: {name}") from exc
        elif entry["kind"] == "batch-readme":
            dates = re.findall(r"\*\*Export date: ([0-9]{4}-[0-9]{2}-[0-9]{2})\*\*", text)
            batches = re.findall(r"^# Batch ([0-9]+) export", text, re.MULTILINE)
            if dates != [manifest["as_of"]] or batches != [str(manifest["batch"])]:
                raise GroundworkError("batch_readme", "Batch README identity/clock differs from manifest")
        else:
            for label, value in re.findall(r"^\*\*(Date|Decision date):\*\*\s*([^\r\n]*)", text, re.MULTILINE):
                checked_date(value.strip(), as_of, f"{name}:{label}")
    if set(indexed_documents) != document_paths or len(indexed_documents) != len(set(indexed_documents)):
        raise GroundworkError("document_index", "Correspondence index and supporting document allowlist differ")
    return {"record_counts": dict(sorted(counts.items())), "documents": len(document_paths)}


def load_batch(root: Path, expected_batch: int):
    if root.is_symlink():
        raise GroundworkError("unsafe_path", "Batch root cannot be a symlink")
    root = root.resolve(strict=True)
    manifest_raw = confined_file(root, "input.manifest.json").read_bytes()
    manifest = read_json(manifest_raw)
    manifest_validate(manifest, expected_batch)  # Reject wrong provenance before source reads.
    contents = {f["path"]: confined_file(root, f["path"]).read_bytes() for f in manifest["files"]}
    summary = validate_content(manifest, contents)
    return manifest, manifest_raw, contents, summary
"""Content-addressed evidence state, with an atomic local HEAD commit point."""

from __future__ import annotations

import os
import tempfile
from contextlib import contextmanager
from pathlib import Path

from .validation import (GroundworkError, HEAD_SCHEMA, STATE_SCHEMA, confined_file,
                         digest, json_bytes, manifest_validate, read_json,
                         schema_validate, validate_content)


class Store:
    def __init__(self, root: Path):
        if root.is_symlink():
            raise GroundworkError("unsafe_path", "State root cannot be a symlink")
        self.root = root.resolve()

    def _object(self, kind: str, sha: str) -> bytes:
        schema_validate(sha, {"type": "string", "pattern": "^[0-9a-f]{64}$"})
        raw = confined_file(self.root, f"objects/{kind}/{sha}").read_bytes()
        if digest(raw) != sha:
            raise GroundworkError("corrupt_state", f"Content hash mismatch in {kind} object")
        return raw

    def current(self):
        if (self.root / "objects").is_symlink():
            raise GroundworkError("unsafe_path", "State object directory cannot be a symlink")
        head_path = self.root / "HEAD.json"
        if head_path.is_symlink():
            raise GroundworkError("unsafe_path", "State HEAD cannot be a symlink")
        if not head_path.exists():
            # Lost HEAD and an abandoned initial candidate are ambiguous. Do not
            # silently initialize over either one or promote an orphan object.
            states = self.root / "objects" / "states"
            if states.is_symlink() or (states.exists() and any(states.iterdir())):
                raise GroundworkError("missing_state", "State objects exist without HEAD; preserve them and investigate")
            return None
        head = read_json(head_path.read_bytes())
        schema_validate(head, HEAD_SCHEMA)
        chain = []
        visited = set()
        sha = head["sha256"]
        while sha is not None:
            if sha in visited:
                raise GroundworkError("corrupt_state", "State chain contains a cycle")
            visited.add(sha)
            state = read_json(self._object("states", sha))
            schema_validate(state, STATE_SCHEMA)
            manifest = state["manifest"]
            manifest_validate(manifest)
            manifest_raw = self._object("blobs", state["manifest_sha256"])
            if read_json(manifest_raw) != manifest:
                raise GroundworkError("corrupt_state", "Stored manifest disagrees with retained original")
            contents = {f["path"]: self._object("blobs", f["sha256"]) for f in manifest["files"]}
            summary = validate_content(manifest, contents)
            chain.append((sha, state, summary))
            sha = state["previous_state_sha256"]
        ordered = list(reversed(chain))
        previous_date = None
        for batch, (_, state, _) in enumerate(ordered, 1):
            manifest = state["manifest"]
            if manifest["batch"] != batch or (previous_date and manifest["as_of"] < previous_date):
                raise GroundworkError("corrupt_state", "State sequence or export clock is invalid")
            previous_date = manifest["as_of"]
        return {"sha256": head["sha256"], "state": chain[0][1], "summary": chain[0][2], "chain": ordered}

    @contextmanager
    def locked(self):
        self.root.mkdir(parents=True, exist_ok=True)
        lock = self.root / ".write-lock"
        try:
            fd = os.open(lock, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError as exc:
            raise GroundworkError("store_busy", "State store is locked; do not remove a live writer's lock") from exc
        try:
            os.close(fd)
            yield
        finally:
            # Cleanup failure after the commit point must not misreport a
            # committed operation as failed. A remaining lock requires review.
            try:
                lock.unlink()
            except OSError:
                pass

    def _put(self, kind: str, raw: bytes) -> str:
        sha = digest(raw)
        directory = self.root / "objects" / kind
        for component in (self.root / "objects", directory):
            if component.is_symlink():
                raise GroundworkError("unsafe_path", "State object directory cannot be a symlink")
        directory.mkdir(parents=True, exist_ok=True)
        path = directory / sha
        try:
            with path.open("xb") as stream:
                stream.write(raw)
                stream.flush()
                os.fsync(stream.fileno())
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != raw:
                raise GroundworkError("corrupt_state", "An immutable object differs from its expected bytes")
        return sha

    def _replace_head(self, sha: str) -> None:
        raw = json_bytes({"format": "credentialing-groundwork-head/1", "sha256": sha})
        fd, name = tempfile.mkstemp(prefix=".head-", dir=self.root)
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(raw)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(name, self.root / "HEAD.json")
        finally:
            if os.path.exists(name):
                os.unlink(name)

    def stage(self, manifest: dict, manifest_raw: bytes, contents: dict[str, bytes], previous: str | None):
        manifest_validate(manifest)
        validate_content(manifest, contents)
        with self.locked():
            current = self.current()
            batch = manifest["batch"]
            manifest_sha = digest(manifest_raw)
            if current and batch == current["state"]["manifest"]["batch"]:
                old = current["state"]
                if manifest_sha == old["manifest_sha256"] and previous == old["previous_state_sha256"]:
                    return self._receipt(current["sha256"], manifest, "unchanged")
                raise GroundworkError("changed_batch", "Retained batch differs; preserve store and use a separate reconstruction")
            expected = current["state"]["manifest"]["batch"] + 1 if current else 1
            if batch != expected:
                raise GroundworkError("batch_sequence", "Only the next batch can extend retained state")
            expected_previous = current["sha256"] if current else None
            if previous != expected_previous:
                raise GroundworkError("predecessor_mismatch", "Explicit previous state does not match verified current state")
            if current and manifest["as_of"] < current["state"]["manifest"]["as_of"]:
                raise GroundworkError("clock_regression", "Export date cannot move backwards")
            # Validate before writing immutable objects or moving HEAD.
            manifest_validate(manifest, batch)
            validate_content(manifest, contents)
            if read_json(manifest_raw) != manifest:
                raise GroundworkError("invalid_structure", "Manifest bytes and parsed manifest disagree")
            for raw in contents.values():
                self._put("blobs", raw)
            self._put("blobs", manifest_raw)
            state = {"format": "credentialing-groundwork-state/1", "phase": "evidence-only",
                     "business_blockers": ["G1", "G2"], "previous_state_sha256": previous,
                     "manifest_sha256": manifest_sha, "manifest": manifest}
            schema_validate(state, STATE_SCHEMA)
            sha = self._put("states", json_bytes(state))
            receipt = self._receipt(sha, manifest, "staged")
            self._replace_head(sha)  # Last fallible operation; this is the commit point.
            return receipt

    @staticmethod
    def _receipt(sha: str, manifest: dict, result: str):
        return {"operation": "evidence-stage", "result": result, "state_sha256": sha,
                "batch": manifest["batch"], "as_of": manifest["as_of"],
                "phase": "evidence-only", "business_blockers": ["G1", "G2"],
                "assessed_snapshot_written": False}
"""Command interface restricted to the learner-authorized foundation."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from .storage import Store
from .validation import GroundworkError, load_batch


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Evidence-only groundwork; business processing is blocked by G1/G2.")
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("check-input", "stage"):
        command = commands.add_parser(name)
        command.add_argument("--input", type=Path, required=True, help="One physical batch directory with input.manifest.json")
        command.add_argument("--batch", type=int, required=True)
        if name == "stage":
            command.add_argument("--store", type=Path, required=True)
            command.add_argument("--previous-state", help="Exact prior state SHA-256; required for continuation")
    command = commands.add_parser("inspect-state")
    command.add_argument("--store", type=Path, required=True)
    commands.add_parser("run", help="Reserved business operation: blocked until source clarification and learner review")
    args = parser.parse_args(argv)
    try:
        if args.command == "run":
            raise GroundworkError("business_blocked", "G1/G2 unresolved; completeness, packet readiness, assessed snapshots and business actions are disabled")
        if args.command == "inspect-state":
            current = Store(args.store).current()
            if current is None:
                raise GroundworkError("missing_state", "No current evidence state; no state was reconstructed")
            result = {"operation": "inspect-state", "phase": "evidence-only", "business_blockers": ["G1", "G2"],
                      "state_sha256": current["sha256"], "summary": current["summary"],
                      "batches": [{"batch": s["manifest"]["batch"], "as_of": s["manifest"]["as_of"],
                                   "state_sha256": sha} for sha, s, _ in current["chain"]],
                      "assessed_snapshot_written": False}
        else:
            if args.command == "stage" and args.store.resolve().is_relative_to(args.input.resolve()):
                raise GroundworkError("unsafe_path", "State store must be outside the input directory")
            manifest, raw, contents, summary = load_batch(args.input, args.batch)
            if args.command == "check-input":
                result = {"operation": "check-input", "result": "structure-valid", "batch": manifest["batch"],
                          "as_of": manifest["as_of"], **summary, "business_blockers": ["G1", "G2"],
                          "assessed_snapshot_written": False}
            else:
                result = Store(args.store).stage(manifest, raw, contents, args.previous_state)
        print(json.dumps(result, sort_keys=True, indent=2))
        return 0
    except GroundworkError as exc:
        print(json.dumps({"result": "operation-failed", "error": exc.code, "message": str(exc),
                          "assessed_snapshot_written": False}, sort_keys=True), file=sys.stderr)
        return 3 if exc.code == "business_blocked" else 2
    except OSError:
        print(json.dumps({"result": "operation-failed", "error": "filesystem_error",
                          "message": "Filesystem operation failed; inspect input/store without overwriting evidence",
                          "assessed_snapshot_written": False}), file=sys.stderr)
        return 2

