const records=[];
for(const label of ["export-root","batch-01","batch-02","batch-03",...["batch-01","batch-02","batch-03"].flatMap(b=>["letters","dispositions","decisions"].map(f=>b+"/"+f))]){
 const r=load(label+"-refetch");if(!r || r.isError)throw Error("Missing successful listing "+label);
 const sc=r.structuredContent;const data=JSON.parse(sc.content);
 records.push({location:label,url:sc.url,title:sc.title,connector_returned_listing_text:sc.content,entries:data.files.map(f=>({id:f.id,title:f.title,mime_type:f.mime_type,url:f.url,size:f.size,modified_time:f.modified_time,kind:f.file_or_folder}))});
}
text(await tools.apply_patch("*** Begin Patch
*** Add File: /Users/user/fellowship/practitioner-credentialing/.local/interview-update/drive-listings.json
+"+JSON.stringify(records,null,2).split("
").join("
+")+"
*** End Patch"));
text(await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
import hashlib,json,subprocess
r=Path('.')
protected=['credentialing','tests','references','snapshot.schema.json','docs/audit/source-readings.json','docs/audit/source-inventory.json','docs/groundwork-checks.json','docs/groundwork-capture.json','docs/reviews']
files=subprocess.check_output(['git','ls-files','--',*protected],text=True).splitlines()
files+=['.local/evidence-store/HEAD.json']
b={'head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'files':{f:hashlib.sha256((r/f).read_bytes()).hexdigest() for f in files}}
(r/'.local/interview-update/baseline.json').write_text(json.dumps(b,indent=2)+'\n')
print('Protected baseline:',len(files),'files; HEAD',b['head'])
PY
entire status --json
entire sessions --help",max_output_tokens:2000}));

